  ) as v(source_key, organisation_name, source_name, source_type, source_url, country_code, data_as_of, metadata)
  loop
    insert into evidence.sources (source_key, organisation_name, source_name, source_type, canonical_url, country_code, active, updated_at)
    values (source_row.source_key, source_row.organisation_name, source_row.source_name, source_row.source_type, source_row.source_url, source_row.country_code, true, now())
    on conflict (source_key) do update set organisation_name=excluded.organisation_name, source_name=excluded.source_name, source_type=excluded.source_type, canonical_url=excluded.canonical_url, country_code=excluded.country_code, active=true, updated_at=now()
    returning id into source_id_value;

    select id into snapshot_id_value from evidence.source_snapshots
    where source_id=source_id_value and source_url=source_row.source_url and data_as_of=source_row.data_as_of
    order by retrieved_at desc limit 1;
    if snapshot_id_value is null then
      insert into evidence.source_snapshots (source_id, source_url, data_as_of, retrieved_at, snapshot_status, metadata)
      values (source_id_value, source_row.source_url, source_row.data_as_of, now(), 'captured', source_row.metadata);
    end if;
  end loop;
end $$;

delete from evidence.metric_observations where scope_type='country' and scope_id in ('IE', 'DE', 'NL', 'BE', 'FR', 'ES', 'SG', 'KR', 'JP', 'NZ', 'NO', 'SE', 'DK', 'FI', 'CH', 'AE') and metric_key in ('full_time_annual_earnings_range', 'average_annual_salary', 'student_living_cost_monthly_range', 'tuition_annual_low', 'tuition_annual_high', 'national_minimum_hourly_wage', 'visa_application_fee', 'student_work_hours_limit');
do $$
declare metric_row record; snapshot_id_value uuid;
