  loop
    select ss.id into snapshot_id_value
    from evidence.sources s join evidence.source_snapshots ss on ss.source_id=s.id
    where s.source_key=metric_row.source_key order by ss.retrieved_at desc limit 1;
    if snapshot_id_value is null then raise exception 'Missing source snapshot for %', metric_row.source_key; end if;
    insert into evidence.metric_observations (metric_key, scope_type, scope_id, value, unit, source_snapshot_id, evidence_kind, confidence, methodology, assumptions, effective_from, review_status, reviewed_at, reviewer_note)
    values (metric_row.metric_key, 'country', metric_row.scope_id, metric_row.value, metric_row.unit, snapshot_id_value, metric_row.evidence_kind, metric_row.confidence, metric_row.methodology, metric_row.assumptions, metric_row.effective_from, 'verified', now(), metric_row.reviewer_note);
  end loop;
end $$;

delete from public.report_metric_evidence_country where scope_type='country' and scope_id in ('IE', 'DE', 'NL', 'BE', 'FR', 'ES', 'SG', 'KR', 'JP', 'NZ', 'NO', 'SE', 'DK', 'FI', 'CH', 'AE') and metric_key in ('full_time_annual_earnings_range', 'average_annual_salary', 'student_living_cost_monthly_range', 'tuition_annual_low', 'tuition_annual_high', 'national_minimum_hourly_wage', 'visa_application_fee', 'student_work_hours_limit');
insert into public.report_metric_evidence_country (scope_type, scope_id, metric_key, value, source_name, source_url, data_as_of, last_verified_at, confidence, evidence_kind, review_status, created_at, updated_at)
select o.scope_type, o.scope_id, o.metric_key, o.value, s.source_name, ss.source_url, coalesce(ss.data_as_of,o.effective_from,current_date), coalesce(o.reviewed_at,o.updated_at,now()), o.confidence, o.evidence_kind, o.review_status, o.created_at, o.updated_at
from evidence.metric_observations o
join evidence.source_snapshots ss on ss.id=o.source_snapshot_id
join evidence.sources s on s.id=ss.source_id
where o.scope_type='country' and o.scope_id in ('IE', 'DE', 'NL', 'BE', 'FR', 'ES', 'SG', 'KR', 'JP', 'NZ', 'NO', 'SE', 'DK', 'FI', 'CH', 'AE') and o.review_status='verified' and o.metric_key in ('full_time_annual_earnings_range', 'average_annual_salary', 'student_living_cost_monthly_range', 'tuition_annual_low', 'tuition_annual_high', 'national_minimum_hourly_wage', 'visa_application_fee', 'student_work_hours_limit');
;
